function plan({ values, previous }) {
  if (!Array.isArray(values) || !Array.isArray(values[0])) throw Error("Sheet needs headers");
  const headers = values[0];
  const column = (name) => {
    const matches = headers.flatMap((v, i) => (v === name ? [i] : []));
    if (matches.length !== 1) throw Error("Missing or duplicate " + name + " header");
    return matches[0];
  };
  const emailColumn = column("Email"),
    statusColumn = column("Status");
  const rows = values.slice(1).map((row, i) => {
    if (!Array.isArray(row)) throw Error("Invalid row");
    return {
      row: i + 2,
      email: String(row[emailColumn] ?? "").trim(),
      status: String(row[statusColumn] ?? ""),
      cells: row,
    };
  });
  const snapshot = rows.map((r) => r.cells);
  if (previous == null) return { snapshot, items: [] };
  if (!Array.isArray(previous)) throw Error("Invalid previous snapshot");
  const seen = new Set(),
    items = [];
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    if (
      JSON.stringify(r.cells) === JSON.stringify(previous[i]) ||
      r.status.trim() ||
      !r.email ||
      seen.has(r.email)
    )
      continue;
    seen.add(r.email);
    items.push({ row: r.row, email: r.email });
  }
  return { snapshot, items };
}

const saved = $getWorkflowStaticData("node");
const result = plan({ values: $input.first().json.values ?? [], previous: saved.snapshot ?? null });
saved.snapshot = result.snapshot;
return result.items.map((item) => ({ json: item }));

function match({ values, current, sheetName, result, returnedEmail }) {
  if (
    !Array.isArray(values) ||
    !Array.isArray(values[0]) ||
    !current ||
    !Number.isInteger(current.row) ||
    current.row < 2
  )
    throw Error("Invalid row");
  if (returnedEmail !== current.email) throw Error("Validation result does not match email");
  if (!["deliverable", "undeliverable", "risky", "unknown"].includes(result))
    throw Error("Invalid validation result");
  const h = values[0],
    find = (n) => {
      const a = h.flatMap((x, i) => (x === n ? [i] : []));
      if (a.length !== 1) throw Error("Missing or duplicate " + n + " header");
      return a[0];
    };
  const e = find("Email"),
    s = find("Status"),
    row = values[current.row - 1];
  if (
    !Array.isArray(row) ||
    String(row[e] ?? "").trim() !== current.email ||
    String(row[s] ?? "").trim()
  )
    throw Error("Row changed before update");
  let col = s + 1,
    letters = "";
  while (col) {
    col--;
    letters = String.fromCharCode(65 + (col % 26)) + letters;
    col = Math.floor(col / 26);
  }
  if (typeof sheetName !== "string" || !sheetName.trim()) throw Error("Missing sheet name");
  return {
    range: "'" + sheetName.replace(/'/g, "''") + "'!" + letters + current.row,
    values: [[result]],
  };
}

const current = $("Select the next email").item.json;
const response = $("Validate the email").item.json;
if (response.error || !response.data) throw Error("Validation failed");
return [
  {
    json: match({
      values: $input.first().json.values ?? [],
      current,
      sheetName: "Emails",
      result: response.data.result,
      returnedEmail: response.data.email,
    }),
  },
];
